    REM_RobotStateInfo_set_rateOfTurn          (remrsip, remrsi->rateOfTurn);
    REM_RobotStateInfo_set_wheelSpeed1         (remrsip, remrsi->wheelSpeed1);
    REM_RobotStateInfo_set_wheelSpeed2         (remrsip, remrsi->wheelSpeed2);
